 {name:'Coração da Terra',short:'Coração do Manto',zone:'MANTO DA TERRA',badge:'NÚCLEO INCANDESCENTE',range:'325 — 400 m',icon:'♨',colors:['#451d42','#81204f','#ad2f45'],gem:['#ad2f45','#de523e','#ffae70','#ffee83'],gemName:'Rubi do manto'}
