export const SKILLS=[
 {id:'rhythm',name:'Ouvido de cristal',desc:'Mais 45 ms para acertar o golpe perfeito.',cost:1,icon:'♫',branch:0},
 {id:'resonance',name:'Ressonância',desc:'Golpes perfeitos causam 3× o dano.',cost:3,requires:'rhythm',icon:'≋',branch:0},
 {id:'fortune',name:'Olhar lapidado',desc:'Receba 30% mais gemas em cada cristal.',cost:1,icon:'◇',branch:1},
 {id:'chain',name:'Veio em cadeia',desc:'Golpes perfeitos atingem também um cristal vizinho.',cost:3,requires:'fortune',icon:'✧',branch:1},
 {id:'force',name:'Punho firme',desc:'A picareta ganha +1 de força permanente.',cost:1,icon:'⚒',branch:2},
 {id:'echo',name:'Eco da picareta',desc:'Sua picareta ecoa um golpe automático a cada 4 batidas.',cost:3,requires:'force',icon:'◈',branch:2}
];
export function rng(seed){let n=seed>>>0;return()=>{n+=0x6D2B79F5;let t=n;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
export function biomeIndex(floor){return Math.min(3,Math.floor((floor-1)/4));}
export function createState(seed=Math.floor(Math.random()*2147483647)){return{version:1,seed,floor:1,best:1,gems:0,essence:0,level:1,skills:[],base:{forge:0,beacon:0},collection:[],totalGems:0,totalPerfect:0,completed:0,run:1,nodes:null,claimed:false};}
export function generateFloor(s){const r=rng(s.seed+s.floor*193+s.run*117);const b=biomeIndex(s.floor);return Array.from({length:8},(_,i)=>{const hp=3+Math.floor((s.floor-1)*.8)+Math.floor(r()*2);return{id:i,x:120+(i%4)*212+(r()-.5)*35,y:i<4?300+(r()-.5)*30:410+(r()-.5)*28,size:25+r()*10,hp,maxHp:hp,value:5+b*5+Math.floor(r()*4),variant:Math.floor(r()*3)};});}
export function ensureFloor(s){if(!s.nodes)s.nodes=generateFloor(s);return s.nodes;}
export function power(s){return s.level+(s.skills.includes('force')?1:0);}
export function upgradeCost(s){return Math.floor(20*Math.pow(1.5,s.level-1)*(s.base.forge?.8:1));}
export function windowMs(s){return 100+(s.skills.includes('rhythm')?45:0)+(s.base.beacon?20:0);}
export function purchaseUpgrade(s){const cost=upgradeCost(s);if(s.gems<cost)return false;s.gems-=cost;s.level++;return true;}
export function purchaseSkill(s,id){const skill=SKILLS.find(x=>x.id===id);if(!skill||s.skills.includes(id)||s.essence<skill.cost||(skill.requires&&!s.skills.includes(skill.requires)))return false;s.essence-=skill.cost;s.skills.push(id);return true;}
export function purchaseBase(s,id){const costs={forge:80,beacon:60};if(!(id in costs)||s.base[id]||s.gems<costs[id])return false;s.gems-=costs[id];s.base[id]=1;return true;}
export function hit(s,id,perfect=false,combo=0,automatic=false){ensureFloor(s);const n=s.nodes.find(x=>x.id===id);if(!n||n.hp<=0||s.claimed)return{destroyed:[],earned:0,damage:0,complete:false};const damage=power(s)*(perfect?(s.skills.includes('resonance')?3:2):1);const targets=[n];if(perfect&&s.skills.includes('chain')){const others=s.nodes.filter(x=>x.hp>0&&x!==n).sort((a,b)=>Math.hypot(a.x-n.x,a.y-n.y)-Math.hypot(b.x-n.x,b.y-n.y));if(others.length)targets.push(others[0]);}const destroyed=[];let earned=0;for(const target of targets){target.hp=Math.max(0,target.hp-damage);if(target.hp===0){destroyed.push(target.id);const value=Math.round(target.value*(s.skills.includes('fortune')?1.3:1)*(perfect?1.5:1)*(1+Math.min(combo,20)*.05));earned+=value;}}s.gems+=earned;s.totalGems+=earned;if(perfect&&!automatic)s.totalPerfect++;if(destroyed.length&&!s.collection.includes(biomeIndex(s.floor)))s.collection.push(biomeIndex(s.floor));const complete=s.nodes.every(x=>x.hp<=0);if(complete){s.claimed=true;s.essence+=1;s.completed++;}return{destroyed,earned,damage,complete};}
export function descend(s){if(!s.claimed||s.floor>=16)return false;s.floor++;s.best=Math.max(s.best,s.floor);s.nodes=generateFloor(s);s.claimed=false;return true;}
export function newExpedition(s){if(s.floor!==16||!s.claimed)return false;s.run++;s.floor=1;s.claimed=false;s.nodes=generateFloor(s);return true;}
export function restoreState(raw){try{const s=JSON.parse(raw);if(s.version!==1||!Number.isInteger(s.floor)||s.floor<1||s.floor>16||!Number.isFinite(s.gems)||s.gems<0||!Number.isInteger(s.level)||s.level<1||s.level>100||!Number.isInteger(s.seed)||!Array.isArray(s.skills)||!Array.isArray(s.collection))return null;const clean={...createState(s.seed),...s};for(const key of ['best','essence','totalGems','totalPerfect','completed','run'])if(!Number.isFinite(clean[key])||clean[key]<0)return null;if(!clean.base||typeof clean.base!=='object')return null;clean.skills=clean.skills.filter(id=>SKILLS.some(k=>k.id===id));if(clean.nodes!==null&&(!Array.isArray(clean.nodes)||clean.nodes.length!==8||clean.nodes.some((n,i)=>n.id!==i||!['hp','maxHp','x','y','size','value','variant'].every(k=>Number.isFinite(n[k]))||n.hp<0||n.hp>n.maxHp)))return null;if(clean.nodes)clean.claimed=clean.nodes.every(n=>n.hp===0);return clean;}catch{return null;}}
